BEGIN;
DO $$ DECLARE actor uuid;s uuid;s2 uuid;c uuid;doc jsonb;first jsonb;r jsonb;review uuid;BEGIN
 INSERT INTO public.admin_users(email,password_hash,role,is_active)VALUES('fictional-privacy-recovery-officer@example.test','fictional-proof','super_admin',true)RETURNING id INTO actor;
 INSERT INTO public.admin_sessions(admin_user_id,token_hash)VALUES(actor,repeat('1',64))RETURNING id INTO s;
 INSERT INTO public.admin_sessions(admin_user_id,token_hash)VALUES(actor,repeat('2',64))RETURNING id INTO s2;
 INSERT INTO public.contact_submissions(name,email,inquiry_type,message,idempotency_key_hash,request_hash)VALUES('Fictional privacy recovery','fictional-privacy-recovery@example.test','general','Fictional privacy recovery content only.',repeat('3',64),repeat('4',64))RETURNING id INTO c;
 doc:=jsonb_build_object('email','fictional-privacy-recovery@example.test','encryptedEmail','v1.fictional-encrypted-email','subjectHash',repeat('5',64),'purposeHash',repeat('6',64),'action','redact','responseIds','[]'::jsonb,'formHashes','[]'::jsonb,'includeSensitive',false);
 r:=public.inspect_person_privacy_write(actor,s,'review',doc,repeat('7',64),repeat('8',64),repeat('9',64));IF(r->>'committed')::boolean OR NOT(r->>'canRetry')::boolean THEN RAISE EXCEPTION 'Unaccepted privacy inspection incorrect';END IF;
 first:=public.mutate_person_privacy_write(actor,s,'review',doc,repeat('7',64),'fictional-proof',repeat('8',64),repeat('9',64),NULL);review:=(first->>'reviewId')::uuid;
 r:=public.mutate_person_privacy_write(actor,s,'review',doc,repeat('7',64),NULL,repeat('8',64),repeat('9',64),NULL);IF r<>first OR(SELECT count(*) FROM public.person_privacy_reviews WHERE actor_id=actor)<>1 THEN RAISE EXCEPTION 'Privacy review replay duplicated';END IF;
 r:=public.inspect_person_privacy_write(actor,s,'review',doc,repeat('7',64),repeat('8',64),repeat('9',64));IF r->'receipt'<>first THEN RAISE EXCEPTION 'Accepted privacy review lost';END IF;
 IF EXISTS(SELECT 1 FROM public.idempotency_keys WHERE scope='person-privacy-write:'||actor||':'||s||':review' AND(result::text LIKE '%Fictional%' OR result::text LIKE '%@%' OR result::text LIKE '%token%')) THEN RAISE EXCEPTION 'Privacy review receipt retained private data';END IF;
 doc:=jsonb_build_object('reviewId',review,'email','fictional-privacy-recovery@example.test','confirmation','REDACT 1 RECORDS');
 UPDATE public.contact_submissions SET revision=revision+1 WHERE id=c;
 r:=public.inspect_person_privacy_write(actor,s,'commit',doc,repeat('7',64),repeat('a',64),repeat('b',64));IF(r->>'canRetry')::boolean THEN RAISE EXCEPTION 'Changed privacy source advertised safe retry';END IF;
 UPDATE public.contact_submissions SET revision=revision-1 WHERE id=c;
 BEGIN PERFORM public.mutate_person_privacy_write(actor,s,'commit',doc,repeat('7',64),NULL,repeat('a',64),repeat('b',64),NULL);RAISE EXCEPTION 'Privacy commit bypassed current proof';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 first:=public.mutate_person_privacy_write(actor,s,'commit',doc,repeat('7',64),'fictional-proof',repeat('a',64),repeat('b',64),NULL);
 r:=public.mutate_person_privacy_write(actor,s,'commit',doc,repeat('7',64),NULL,repeat('a',64),repeat('b',64),NULL);IF r<>first OR(SELECT revision FROM public.contact_submissions WHERE id=c)<>2 OR(SELECT email FROM public.contact_submissions WHERE id=c)<>'' THEN RAISE EXCEPTION 'Privacy accepted replay changed retained record';END IF;
 r:=public.inspect_person_privacy_write(actor,s,'commit',doc,repeat('7',64),repeat('a',64),repeat('b',64));IF NOT(r->>'committed')::boolean OR(r->>'canRetry')::boolean OR r->'receipt'<>first THEN RAISE EXCEPTION 'Privacy accepted receipt inspection incorrect';END IF;
 BEGIN PERFORM public.inspect_person_privacy_write(actor,s2,'commit',doc,repeat('7',64),repeat('a',64),repeat('b',64));RAISE EXCEPTION 'Privacy receipt crossed session';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 BEGIN PERFORM public.inspect_person_privacy_write(actor,s,'commit',doc,repeat('7',64),repeat('a',64),repeat('c',64));RAISE EXCEPTION 'Privacy changed original body';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'CONFLICT' THEN RAISE;END IF;END;
 UPDATE public.admin_users SET role='admin' WHERE id=actor;
 BEGIN PERFORM public.inspect_person_privacy_write(actor,s,'commit',doc,repeat('7',64),repeat('a',64),repeat('c',64));RAISE EXCEPTION 'Privacy authority checked after hash';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 UPDATE public.admin_users SET role='super_admin' WHERE id=actor;
 UPDATE public.idempotency_keys SET expires_at=now()-interval '1 second' WHERE scope='person-privacy-write:'||actor||':'||s||':commit';
 BEGIN PERFORM public.inspect_person_privacy_write(actor,s,'commit',doc,repeat('7',64),repeat('a',64),repeat('b',64));RAISE EXCEPTION 'Expired privacy receipt disclosed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVALID_STATE' THEN RAISE;END IF;END;
 doc:=jsonb_build_object('email','fictional-privacy-recovery@example.test','encryptedEmail','v1.fictional-encrypted-email','subjectHash',repeat('5',64),'purposeHash',repeat('6',64),'action','export','responseIds','[]'::jsonb,'formHashes','[]'::jsonb,'includeSensitive',false);
 r:=public.mutate_person_privacy_write(actor,s,'review',doc,repeat('d',64),'fictional-proof',repeat('e',64),repeat('f',64),NULL);review:=(r->>'reviewId')::uuid;
 doc:=jsonb_build_object('reviewId',review,'email','fictional-privacy-recovery@example.test','confirmation','EXPORT 0 RECORDS');
 first:=public.mutate_person_privacy_write(actor,s,'commit',doc,repeat('d',64),'fictional-proof',repeat('0',64),repeat('1',64),NULL);IF NOT(first?'export') THEN RAISE EXCEPTION 'First export response missing';END IF;
 r:=public.inspect_person_privacy_write(actor,s,'commit',doc,repeat('d',64),repeat('0',64),repeat('1',64));IF r->'receipt'?'export' OR NOT(r->'receipt'->>'downloadExpired')::boolean THEN RAISE EXCEPTION 'Privacy export inspection replayed private bytes';END IF;
 r:=public.mutate_person_privacy_write(actor,s,'commit',doc,repeat('d',64),NULL,repeat('0',64),repeat('1',64),NULL);IF r?'export' OR NOT(r->>'downloadExpired')::boolean THEN RAISE EXCEPTION 'Privacy accepted export replayed private bytes';END IF;
 IF has_function_privilege('anon','public.inspect_person_privacy_write(uuid,uuid,text,jsonb,text,text,text)','EXECUTE') OR has_function_privilege('authenticated','public.mutate_person_privacy_write(uuid,uuid,text,jsonb,text,text,text,text,uuid)','EXECUTE') OR NOT has_function_privilege('service_role','public.inspect_person_privacy_write(uuid,uuid,text,jsonb,text,text,text)','EXECUTE') THEN RAISE EXCEPTION 'Privacy recovery grants incorrect';END IF;
END $$;
ROLLBACK;
